 leituras e registrar falhas ou desvios identificados.","frequency":"Quinzenal","start_date":"2027-05-03","due_date":"2027-12-20","expected_deliverable":"Registros quinzenais de testes e integridade dos dados.","priority":"high","execution_condition":"","responsible_name":"A definir","responsible_user_id":null,"notes":"","effort_points":null},{"area":"Telemetria","name":"Calibrar sensores e revisar parâmetros de aquisição","activity_type":"condicional","description":"Realizar calibração e ajuste de parâmetros quando os testes identificarem desvios, leituras inconsistentes ou troca de sensores.","execution_condition":"Executar quando testes de validação identificarem desvio de leitura, inconsistência ou substituição de sensor.","start_date":"2027-05-03","due_date":"2027-11-30","expected_deliverable":"Registros de calibração e parâmetros revisados, quando aplicável.","priority":"medium","frequency":"","responsible_name":"A definir","responsible_user_id":null,"notes":"","effort_points":null},{"area":"Telemetria","name":"Validar transmissão e integração dos dados de telemetria","activity_type":"marco","description":"Validar comunicação, transmissão, registro e disponibilidade dos dados coletados durante testes integrados da embarcação.","start_date":"2027-09-01","due_date":"2027-11-30","expected_deliverable":"Relatório de validação da telemetria integrada.","priority":"high","frequency":"","execution_condition":"","responsible_name":"A definir","responsible_user_id":null,"notes":"","effort_points":null}]
$activities$::jsonb) as x(
    area text,
    name text,
    activity_type text,
    description text,
    start_date date,
    due_date date,
    expected_deliverable text,
    notes text,
    priority text,
    frequency text,
    execution_condition text,
    responsible_name text,
    responsible_user_id uuid,
    effort_points smallint
  )
), resolved as (
  select p.*, a.id as area_id
  from payload p
  join public.areas a on a.name = p.area and a.is_active = true
  where not exists (
    select 1 from public.activities existing
    where existing.area_id = a.id and existing.name = p.name
  )
), admin_user as (
  select user_id
  from public.profiles
  where status = 'active' and role = 'admin'
  order by created_at
  limit 1
)
insert into public.activities (
  area_id, name, description, activity_type, frequency,
  execution_condition, responsible_name, responsible_user_id,
  start_date, due_date, expected_deliverable, notes, created_by,
  flow_status, priority, effort_points
)
select
  r.area_id, r.name, coalesce(r.description, ''),
  r.activity_type::public.activity_type,
  coalesce(r.frequency, ''), coalesce(r.execution_condition, ''),
  coalesce(r.responsible_name, 'A definir'), r.responsible_user_id,
  r.start_date, r.due_date, coalesce(r.expected_deliverable, ''),
  coalesce(r.notes, ''), admin_user.user_id,
  'backlog', coalesce(r.priority, 'medium'), r.effort_points
from resolved r
cross join admin_user
where r.activity_type in ('marco', 'pontual', 'rotina', 'condicional')
  and (r.start_date is null or r.due_date is null or r.start_date <= r.due_date);

alter table public.calendar_events enable trigger calendar_events_set_actor;

commit;
